  "imported_at"
 ],
 "properties": {
  "origin_kind": {
   "type": "string",
   "enum": [
    "manual",
    "github",
    "system-spec-harness",
    "system-dev-planner",
    "generated"
   ]
  },
  "source_plugin": {
   "type": [
    "string",
    "null"
   ]
  },
  "source_path": {
   "type": [
    "string",
    "null"
   ],
   "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"
  },
  "source_version": {
   "type": [
    "string",
    "null"
   ]
  },
  "source_digest": {
   "type": [
    "string",
    "null"
   ],
   "pattern": "^[a-f0-9]{64}$"
  },
  "imported_at": {
   "type": [
    "string",
    "null"
   ],
   "format": "date-time"
  }
 },
 "additionalProperties": false,
 "description": "引用・import元を追跡し、C19およびexternal plugin system-dev-planner由来のimportが外部正本を利用したことを検証する"
}
###  confirmation_evidence
{
 "type": "object",
 "required": [
  "evaluator",
  "evidence_ref",
  "evaluated_digest"
 ],
 "properties": {
  "evaluator": {
   "type": [
    "string",
    "null"
   ]
  },
  "evidence_ref": {
   "type": [
    "string",
    "null"
   ]
  },
  "evaluated_digest": {
   "type": [
    "string",
    "null"
   ],
   "pattern": "^[a-f0-9]{64}$"
  }
 },
 "additionalProperties": false,
 "description": "confirmation/evaluationを同一artifact digestへpinしstale PASSを拒否する"
}
###  confirmation_status
{
 "type": "string",
 "enum": [
  "draft",
  "confirmed",
  "superseded"
 ],
 "description": "内容確定状態。system plan入力はspecification/architectureがconfirmedであることを要求する"
}
###  evaluation_status
{
 "type": "string",
 "enum": [
  "pending",
  "pass",
  "fail",
  "stale"
 ],
 "description": "独立評価状態。C14/C15/C04はpass以外をIssue起票・推薦・実装handoff対象にしない"
}
###  implementation_readiness
{
 "type": "object",
 "required": [
  "status",
  "missing_sections",
  "checked_at"
 ],
 "properties": {
  "status": {
   "type": "string",
   "enum": [
    "complete",
    "incomplete",
    "not_applicable"
   ]
  },
  "missing_sections": {
   "type": "array",
   "items": {
    "type": "string"
   },
   "uniqueItems": true
  },
  "checked_at": {
   "type": [
    "string",
    "null"
   ],
   "format": "date-time"
  }
 },
 "additionalProperties": false,
 "description": "template-contract.jsonの必須field/section、placeholder、conditional template、参照解決を検査した実装着手準備状態"
}
###  file_path
{
 "type": "string",
 "pattern": "^(issues|tasks|specs|architecture|features|docs)/.+\\.md$",
 "description": "全artifactが持つ正規root配下の人間可読Markdownへの参照。graph_node_idは不変、file_pathはrouting policyとpartition状態から再計算可能な派生値。feature は features/ 配下 (MM-02)"
}
###  template_id
{
 "type": "string",
 "enum": [
  "issue",
  "task",
  "document",
  "specification",
  "architecture",
  "feature"
 ],
 "description": "artifact_kindから自動選択した基底テンプレート"
}
###  template_version
{
 "type": "string",
 "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$",
 "description": "生成時に使用したテンプレート契約版。正本更新時は既存文書を全書換せずmigration previewへ使う"
}
###  artifact_subtypes
{
 "type": "array",
 "items": {
  "type": "string",
  "enum": [
   "frontend",
   "backend",
   "infrastructure",
   "data",
   "security",
   "api"
  ]
 },
 "uniqueItems": true,
 "description": "architecture subtype または specification の conditional template。architecture は1種以上、非該当kindは空配列を許す"
}
###  classification_confidence
{
 "type": "number",
 "minimum": 0,
 "maximum": 1,
 "description": "artifact_kind/domain/project_id自動分類のconfidence。0.80以上かつ第2候補との差0.15以上で自動確定、それ未満はpreview後に確認"
}
###  classification_reason
{
 "type": "string",
 "minLength": 1,
 "description": "自動分類の根拠。previewと監査証跡へ表示する"
}
###  classification_candidates
{
 "type": "array",
 "items": {
  "type": "object",
  "required": [
   "artifact_kind",
   "confidence",
   "candidate_path"
  ],
  "properties": {
   "artifact_kind": {
    "$ref": "#/$defs/artifactKind"
   },
   "confidence": {
    "type": "number",
    "minimum": 0,
    "maximum": 1
   },
   "candidate_path": {
    "type": "string"
   }
  },
  "additionalProperties": false
 },
 "description": "previewに表示する上位候補。ユーザーへ保存先そのものを入力させない"
}
###  github_publication
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "mode",
  "project_aliases",
  "labels",
  "milestone"
 ],
 "properties": {
  "mode": {
   "type": "string",
   "enum": [
    "local_only",
    "issue",
    "issue_and_projects"
   ]
  },
  "project_aliases": {
   "type": "array",
   "uniqueItems": true,
   "items": {
    "type": "string",
    "minLength": 1
   }
  },
  "labels": {
   "type": "array",
   "uniqueItems": true,
   "items": {
    "type": "string",
    "minLength": 1
   }
  },
  "milestone": {
   "type": [
    "string",
    "null"
   ]
  }
 },
 "description": "task specification確定後の外部publication intent。project_aliases空かつmode=issue_and_projectsの場合はrepo configのdefault/auto-add targetを使う。draft/unconfirmed/evaluation非pass/readiness非completeではmodeに関わらず外部write禁止。"
}
###  issue_linkage
{
 "type": [
  "object",
  "null"
 ],
 "description": "GitHub Issue との紐付け。C14 (decompose) が起票した時点でissue_numberを書き込み、C03 (sync) はlinkage済みノードを新規起票せずupdated_at比較のみを行う (create→syncの起票非重複契約・要件C7)",
 "properties": {
  "issue_number": {
   "type": "integer"
  },
  "repo": {
   "type": "string"
  },
  "linked_at": {
   "type": "string",
   "format": "date-time"
  }
 },
 "required": [
  "issue_number",
  "repo"
 ]
}
